1	// What "works offline" means for Killedar, as plain data: the app's own files (shell, fort notes,
2	// TabPFN's climb times, narration) and the on-device Gemma guide. Pure, so the UI is testable.
3	
4	export type StepId = "files" | "guide";
5	
6	/** "no-space": the browser refused to store more (phone full, or a private/incognito window). */
7	export type StepStatus = "missing" | "working" | "done" | "unsupported" | "failed" | "no-space";
8	
9	export interface OfflineStep {
10	  id: StepId;
11	  status: StepStatus;
12	  /** 0..1 */
13	  fraction: number;
14	  /** Short progress text, e.g. "12 of 30 files" or WebLLM's download message. */
15	  detail: string;
...
42	 */
43	export function overallFraction(r: OfflineReport): number {
44	  const guideCounts = r.guide.status !== "unsupported";
45	  const fileWeight = guideCounts ? 0.02 : 1;
46	  const done = (s: OfflineStep) => (s.status === "done" ? 1 : clamp01(s.fraction));
47	  return clamp01(fileWeight * done(r.files) + (guideCounts ? (1 - fileWeight) * done(r.guide) : 0));
48	}
49	
50	/** True for the browser's "storage full" error, however the library wrapped it. */
51	export function isNoSpaceError(e: unknown): boolean {
52	  for (let cur = e, depth = 0; cur && depth < 4; cur = (cur as { cause?: unknown }).cause, depth++) {
53	    const { name, message } = cur as { name?: unknown; message?: unknown };
54	    if (name === "QuotaExceededError" || (typeof message === "string" && /quota/i.test(message))) return true;
55	  }
56	  return false;
57	}
58	
59	/** WebLLM's progress line, without its trailing advice: "Fetching param cache[26/42]: 720MB fetched. 51% completed". */
60	export function shortProgressText(text: string): string {
61	  return text.split(/,? \d+ secs? elapsed| It can take/)[0]?.trim() ?? text;
62	}
63	
64	export function step(id: StepId, status: StepStatus, fraction = status === "done" ? 1 : 0, detail = ""): OfflineStep {
65	  return { id, status, fraction: clamp01(fraction), detail };
66	}
67	
68	const clamp01 = (n: number) => (Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0);

